import foldVectors from './__vectors__/time-clock-fold-vectors.json';
import sweepVectors from './__vectors__/time-clock-sweep-vectors.json';
import { foldEvents } from './fold.service';
import { autoClockOutAt, sweepAt } from './sweep.util';

/**
 * The cases the iPad's Swift fold and sweep are held to (iOS Plan 43). Both repos keep the
 * same two files, generated by `scripts/tc-vectors.cjs`; this spec fails when the server's
 * code stops giving the answers the iPad was built against.
 *
 * They record what the code does, not what it should do: a deliberate change to the fold
 * or the sweep regenerates them here and in the iPad's PatrolKitTests/Fixtures together.
 */

const iso = (d: Date | null) => (d ? d.toISOString().replace('.000Z', 'Z') : null);

describe('time clock vectors shared with the iPad', () => {
  describe.each(foldVectors.cases)('fold: $name', (c) => {
    it('folds to the recorded entries and event statuses', () => {
      const { entries, eventStatus } = foldEvents(c.events.map((e) => ({ ...e, occurredAt: new Date(e.occurredAt) })));

      expect(
        entries.map((e) => ({
          id: e.id, resortId: e.resortId, dutyType: e.dutyType, dutyNote: e.dutyNote,
          clockInAt: iso(e.clockInAt), clockOutAt: iso(e.clockOutAt), status: e.status,
          closeReason: e.closeReason, flagged: e.flagged, closeEventId: e.closeEventId,
        })),
      ).toEqual(c.entries);
      expect(Object.fromEntries(eventStatus)).toEqual(c.eventStatus);
    });
  });

  describe.each(sweepVectors.cases)('sweep: $name', (c) => {
    it('sweeps and auto-closes at the recorded instants', () => {
      const at = new Date(c.clockInAt);

      expect(iso(sweepAt(at, c.timeZone, c.autoCloseLocalTime))).toBe(c.sweepAt);
      expect(iso(autoClockOutAt(at, c.timeZone, c.autoCloseLocalTime, c.autoCloseAfterHours))).toBe(c.clockOutAt);
    });
  });
});
